Then, create a scheduled task that runs at a certain interval:

@Component
public class QueryScheduler {

    private final QueryService queryService;
    private final String queryFilePath = "path/to/your/query.sql";
    private final String resultFilePath = "path/to/your/result.txt";

    public QueryScheduler(QueryService queryService) {
        this.queryService = queryService;
    }

    @Scheduled(fixedRate = 60000) // every 60 seconds
    public void runQuery() {
        try {
            String query = queryService.readQueryFromFile(queryFilePath);
            List<Map<String, Object>> results = queryService.executeQuery(query);

            // Convert results to a string format and write to file
            StringBuilder sb = new StringBuilder();
            for (Map<String, Object> row : results) {
                for (Map.Entry<String, Object> entry : row.entrySet()) {
                    sb.append(entry.getKey()).append(": ").append(entry.getValue()).append(", ");
                }
                sb.append("\n");
            }

            Files.write(Paths.get(resultFilePath), sb.toString().getBytes());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

